-- Speglar det som lades på databasen 2026-09-16 via apply_migration i sex delar:
--   mhz2_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   mhz2_order_code_from_catalogue_part_02  (värdelista, rensning av regler)
--   mhz2_order_code_from_catalogue_part_03  (regler 1–20)
--   mhz2_order_code_from_catalogue_part_04  (regler 21–40)
--   mhz2_order_code_from_catalogue_part_05  (regler 41–49, dokumentkarta, produktraden SMC-MHZ2)
--   mhz2_order_code_from_catalogue_part_06  (SMC-MHZ2 mode_of_operation även enkelverkande)
-- Katalogen smc-kat-mhz2-std.pdf (401 stycken) lästes in i knowledge_chunks samma dag med
-- scripts/ingest-catalogues.py (tillfällig laddfunktion, släppt och verifierad borta efteråt).
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts mhz2):
--   regler  49   md5 7eb978ca1bef6febdf635c9c0f2e0b22   villkor d83f5883761bb45130b86db6422c5edf
--   värden  61   md5 e1524d199e4c95f7a03b55f72a039b83
--   schema       md5 933b285ec3794aeb2242763687dadbb6
-- Verifierat live: /sv/configurator/mhz2 bygger MHZ2-16D-M9BW (nyckelns exempel sida 497),
-- stoppar kroppsalternativ K på dubbelverkande (sida 499), D-F8N på ø10 (sida 497) och -X51
-- med fingerläge N1 (sida 548, not 2).
--
-- MHZ2: beställnyckeln enligt SMC Parallel Type Air Gripper MHZ2 Series (sida 496–499).
-- GENERERAD ur src/lib/catalog/mhz2.ts -- redigera inte för hand.
--
-- Rättar familjen mhz2, som hade mallen 'MHZ2-{size}-{grip_type}{options}'
-- med flerval och ett slag per käft som MHZ2 inte har. SMC:s kod är
-- MHZ2-{ø}{verkan}{finger}{kropp}-{givare}{kabel}{antal}-{special}, t.ex.
-- MHZ2-16D-M9BW (nyckelns exempel sida 497). Verkan, fingerläge,
-- kroppsalternativ, givare med kabellängd och antal och specialutförandena
-- fanns inte alls. Katalogen smc-kat-mhz2.pdf var kompaktserien JMHZ2;
-- standardseriens kapitel hämtades 2026-09-16 (smc-kat-mhz2-std.pdf).
--
-- SMC-MHZ2 får katalogens beskrivning, borrningar, slag, gripkraft och data.

begin;

create schema if not exists backup;
create table if not exists backup.mhz2_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'mhz2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'mhz2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'mhz2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-MHZ2-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"6","label":"ø6 mm"},{"v":"10","label":"ø10 mm"},{"v":"16","label":"ø16 mm"},{"v":"20","label":"ø20 mm"},{"v":"25","label":"ø25 mm"},{"v":"32","label":"ø32 mm"},{"v":"40","label":"ø40 mm"}]},{"id":"action","step":2,"title_sv":"Verkan","title_en":"Action","required":true,"type":"single_select","options":[{"v":"D","label":"Dubbelverkande"},{"v":"S","label":"Enkelverkande, normalt öppen (yttre grepp)"},{"v":"C","label":"Enkelverkande, normalt stängd (inre grepp)"}]},{"id":"finger","step":3,"title_sv":"Fingerläge/-alternativ (standard är basutförande)","title_en":"Finger position/option (basic type is standard)","required":false,"type":"single_select","options":[{"v":"1","label":"Sidogängat fingerfäste"},{"v":"2","label":"Genomgående hål i öppnings-/stängningsriktningen"},{"v":"3","label":"Platta fingrar"},{"v":"N","label":"Smal typ, basutförande (MHQ2-kompatibel; ø10–25)"},{"v":"N1","label":"Smal typ, sidogängat fingerfäste (ø10–25)"},{"v":"N2","label":"Smal typ, genomgående hål (ø10–25)"}]},{"id":"body","step":4,"title_sv":"Kroppsalternativ, ändtapp (ø10–25)","title_en":"Body option, end boss type (ø10–25)","required":false,"type":"single_select","options":[{"v":"E","label":"Ändtapp, sidoportad (ø10: M3, ø16–25: M5)"},{"v":"W","label":"Ändtapp, axiella portar med ø4-koppling för koaxialslang (bara dubbelverkande)"},{"v":"K","label":"Ändtapp, axiell port med ø4-koppling (bara enkelverkande)"},{"v":"M","label":"Ändtapp, axiell port M5 (bara enkelverkande)"}]},{"id":"switch","step":5,"title_sv":"Magnetgivare (kroppen har inbyggd magnet)","title_en":"Auto switch (the body has a built-in magnet)","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinkelrät anslutning"},{"v":"F8N","label":"D-F8N, 3-tråd NPN, kort, vinkelrät anslutning (inte ø10)"},{"v":"M9P","label":"D-M9P, 3-tråd PNP"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinkelrät anslutning"},{"v":"F8P","label":"D-F8P, 3-tråd PNP, kort, vinkelrät anslutning (inte ø10)"},{"v":"M9B","label":"D-M9B, 2-tråd"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinkelrät anslutning"},{"v":"F8B","label":"D-F8B, 2-tråd, kort, vinkelrät anslutning (inte ø10)"},{"v":"M9NW","label":"D-M9NW, 3-tråd NPN, tvåfärgsindikering"},{"v":"M9NWV","label":"D-M9NWV, 3-tråd NPN, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9PW","label":"D-M9PW, 3-tråd PNP, tvåfärgsindikering"},{"v":"M9PWV","label":"D-M9PWV, 3-tråd PNP, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9NA","label":"D-M9NA, 3-tråd NPN, vattentät, tvåfärgsindikering"},{"v":"M9NAV","label":"D-M9NAV, 3-tråd NPN, vattentät, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9PA","label":"D-M9PA, 3-tråd PNP, vattentät, tvåfärgsindikering"},{"v":"M9PAV","label":"D-M9PAV, 3-tråd PNP, vattentät, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, tvåfärgsindikering"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, tvåfärgsindikering, vinkelrät anslutning"}]},{"id":"lead","step":6,"title_sv":"Givarens kabellängd (standard 0,5 m)","title_en":"Lead wire length (0.5 m is standard)","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":7,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre givare (n st; ø10–40)"},{"v":"4","label":"Fyra givare (n st; ø10–40)"}]},{"id":"mto","step":8,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"X4","label":"-X4 Värmebeständig (100 °C)"},{"v":"X5","label":"-X5 Fluorgummitätning"},{"v":"X7","label":"-X7 Fjäderassistans i stängningsriktningen"},{"v":"X12","label":"-X12 Fjäderassistans i öppningsriktningen"},{"v":"X46","label":"-X46 Inbyggd strypskruv för fingerhastigheten (ø10–25, dubbelverkande)"},{"v":"X50","label":"-X50 Utan magnet"},{"v":"X51","label":"-X51 Platta fingrar kompatibla med MHQG2 (Nil) eller MHQ2 (N) (ø10–25)"},{"v":"X53","label":"-X53 EPDM-tätning och fluorfett"},{"v":"X56","label":"-X56 Axiella portar"},{"v":"X63","label":"-X63 Fluorfett"},{"v":"X79","label":"-X79 Fett för livsmedelsmaskiner och fluorfett"},{"v":"X79A","label":"-X79A Fett för livsmedelsmaskiner"},{"v":"X81A","label":"-X81A Korrosionsskyddade fingrar"},{"v":"X81B","label":"-X81B Korrosionsskyddade fingrar och styrning"}]}]}'::jsonb,
        'SMC MHZ2 parallellgripdon ø6–40', 'SMC MHZ2 parallel gripper ø6–40', 'gripper')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Parallellgripdon ø6–40, två fingrar, dubbel- eller enkelverkande',
  description = 'SMC MHZ2 parallel type air gripper, two fingers, ø6–40, double acting or single acting (normally open/closed), narrow fingers and end boss body options for ø10–25, solid state auto switches.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'MHZ2-{bore}{action}{finger}{body}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-MHZ2-V1'
where slug = 'mhz2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'mhz2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'mhz2';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"bore","label":"Kolvdiameter","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"action","label":"Verkan","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"finger","label":"Fingerläge/-alternativ (standard är basutförande)","param_type":"select","sort_order":3,"required":false,"min_value":null,"max_value":null},{"param_key":"body","label":"Kroppsalternativ, ändtapp (ø10–25)","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"switch","label":"Magnetgivare (kroppen har inbyggd magnet)","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Givarens kabellängd (standard 0,5 m)","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"count","label":"Antal givare","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'mhz2';

insert into configurator_param_values (param_id, code, label, sort_order)
select p.id, r.code, r.label, r.sort_order
from jsonb_to_recordset('[{"param_key":"bore","code":"6","label":"ø6 mm","sort_order":0},{"param_key":"bore","code":"10","label":"ø10 mm","sort_order":1},{"param_key":"bore","code":"16","label":"ø16 mm","sort_order":2},{"param_key":"bore","code":"20","label":"ø20 mm","sort_order":3},{"param_key":"bore","code":"25","label":"ø25 mm","sort_order":4},{"param_key":"bore","code":"32","label":"ø32 mm","sort_order":5},{"param_key":"bore","code":"40","label":"ø40 mm","sort_order":6},{"param_key":"action","code":"D","label":"Dubbelverkande","sort_order":0},{"param_key":"action","code":"S","label":"Enkelverkande, normalt öppen (yttre grepp)","sort_order":1},{"param_key":"action","code":"C","label":"Enkelverkande, normalt stängd (inre grepp)","sort_order":2},{"param_key":"finger","code":"1","label":"Sidogängat fingerfäste","sort_order":0},{"param_key":"finger","code":"2","label":"Genomgående hål i öppnings-/stängningsriktningen","sort_order":1},{"param_key":"finger","code":"3","label":"Platta fingrar","sort_order":2},{"param_key":"finger","code":"N","label":"Smal typ, basutförande (MHQ2-kompatibel; ø10–25)","sort_order":3},{"param_key":"finger","code":"N1","label":"Smal typ, sidogängat fingerfäste (ø10–25)","sort_order":4},{"param_key":"finger","code":"N2","label":"Smal typ, genomgående hål (ø10–25)","sort_order":5},{"param_key":"body","code":"E","label":"Ändtapp, sidoportad (ø10: M3, ø16–25: M5)","sort_order":0},{"param_key":"body","code":"W","label":"Ändtapp, axiella portar med ø4-koppling för koaxialslang (bara dubbelverkande)","sort_order":1},{"param_key":"body","code":"K","label":"Ändtapp, axiell port med ø4-koppling (bara enkelverkande)","sort_order":2},{"param_key":"body","code":"M","label":"Ändtapp, axiell port M5 (bara enkelverkande)","sort_order":3},{"param_key":"switch","code":"M9N","label":"D-M9N, 3-tråd NPN","sort_order":0},{"param_key":"switch","code":"M9NV","label":"D-M9NV, 3-tråd NPN, vinkelrät anslutning","sort_order":1},{"param_key":"switch","code":"F8N","label":"D-F8N, 3-tråd NPN, kort, vinkelrät anslutning (inte ø10)","sort_order":2},{"param_key":"switch","code":"M9P","label":"D-M9P, 3-tråd PNP","sort_order":3},{"param_key":"switch","code":"M9PV","label":"D-M9PV, 3-tråd PNP, vinkelrät anslutning","sort_order":4},{"param_key":"switch","code":"F8P","label":"D-F8P, 3-tråd PNP, kort, vinkelrät anslutning (inte ø10)","sort_order":5},{"param_key":"switch","code":"M9B","label":"D-M9B, 2-tråd","sort_order":6},{"param_key":"switch","code":"M9BV","label":"D-M9BV, 2-tråd, vinkelrät anslutning","sort_order":7},{"param_key":"switch","code":"F8B","label":"D-F8B, 2-tråd, kort, vinkelrät anslutning (inte ø10)","sort_order":8},{"param_key":"switch","code":"M9NW","label":"D-M9NW, 3-tråd NPN, tvåfärgsindikering","sort_order":9},{"param_key":"switch","code":"M9NWV","label":"D-M9NWV, 3-tråd NPN, tvåfärgsindikering, vinkelrät anslutning","sort_order":10},{"param_key":"switch","code":"M9PW","label":"D-M9PW, 3-tråd PNP, tvåfärgsindikering","sort_order":11},{"param_key":"switch","code":"M9PWV","label":"D-M9PWV, 3-tråd PNP, tvåfärgsindikering, vinkelrät anslutning","sort_order":12},{"param_key":"switch","code":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering","sort_order":13},{"param_key":"switch","code":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinkelrät anslutning","sort_order":14},{"param_key":"switch","code":"M9NA","label":"D-M9NA, 3-tråd NPN, vattentät, tvåfärgsindikering","sort_order":15},{"param_key":"switch","code":"M9NAV","label":"D-M9NAV, 3-tråd NPN, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":16},{"param_key":"switch","code":"M9PA","label":"D-M9PA, 3-tråd PNP, vattentät, tvåfärgsindikering","sort_order":17},{"param_key":"switch","code":"M9PAV","label":"D-M9PAV, 3-tråd PNP, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":18},{"param_key":"switch","code":"M9BA","label":"D-M9BA, 2-tråd, vattentät, tvåfärgsindikering","sort_order":19},{"param_key":"switch","code":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":20},{"param_key":"lead","code":"M","label":"1 m kabel","sort_order":0},{"param_key":"lead","code":"L","label":"3 m kabel","sort_order":1},{"param_key":"lead","code":"Z","label":"5 m kabel","sort_order":2},{"param_key":"count","code":"S","label":"En givare (standard är två)","sort_order":0},{"param_key":"count","code":"3","label":"Tre givare (n st; ø10–40)","sort_order":1},{"param_key":"count","code":"4","label":"Fyra givare (n st; ø10–40)","sort_order":2},{"param_key":"mto","code":"X4","label":"-X4 Värmebeständig (100 °C)","sort_order":0},{"param_key":"mto","code":"X5","label":"-X5 Fluorgummitätning","sort_order":1},{"param_key":"mto","code":"X7","label":"-X7 Fjäderassistans i stängningsriktningen","sort_order":2},{"param_key":"mto","code":"X12","label":"-X12 Fjäderassistans i öppningsriktningen","sort_order":3},{"param_key":"mto","code":"X46","label":"-X46 Inbyggd strypskruv för fingerhastigheten (ø10–25, dubbelverkande)","sort_order":4},{"param_key":"mto","code":"X50","label":"-X50 Utan magnet","sort_order":5},{"param_key":"mto","code":"X51","label":"-X51 Platta fingrar kompatibla med MHQG2 (Nil) eller MHQ2 (N) (ø10–25)","sort_order":6},{"param_key":"mto","code":"X53","label":"-X53 EPDM-tätning och fluorfett","sort_order":7},{"param_key":"mto","code":"X56","label":"-X56 Axiella portar","sort_order":8},{"param_key":"mto","code":"X63","label":"-X63 Fluorfett","sort_order":9},{"param_key":"mto","code":"X79","label":"-X79 Fett för livsmedelsmaskiner och fluorfett","sort_order":10},{"param_key":"mto","code":"X79A","label":"-X79A Fett för livsmedelsmaskiner","sort_order":11},{"param_key":"mto","code":"X81A","label":"-X81A Korrosionsskyddade fingrar","sort_order":12},{"param_key":"mto","code":"X81B","label":"-X81B Korrosionsskyddade fingrar och styrning","sort_order":13}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'mhz2';

delete from config_rules where schema_id = 'SCHEMA-MHZ2-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-MHZ2-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"in":[{"var":"finger"},["N","N1","N2"]]},{"in":[{"var":"bore"},["6","32","40"]]}]},"message_sv":"Smal typ N, N1 och N2 (MHQ2-kompatibel) finns bara för ø10, 16, 20 och 25, inte ø6, 32 och 40 (sida 496–498).","message_en":"The narrow type N, N1 and N2 (MHQ2 compatible) exists only for ø10, 16, 20 and 25, not ø6, 32 and 40 (pages 496–498).","goto_step":"mhz2-finger"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"body"},""]},{"in":[{"var":"bore"},["6","32","40"]]}]},"message_sv":"Kroppsalternativen E, W, K och M (ändtapp) finns bara för ø10, 16, 20 och 25, inte ø6, 32 och 40 (sida 499).","message_en":"The body options E, W, K and M (end boss) exist only for ø10, 16, 20 and 25, not ø6, 32 and 40 (page 499).","goto_step":"mhz2-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"W"]},{"in":[{"var":"action"},["S","C"]]}]},"message_sv":"Kroppsalternativet W finns bara dubbelverkande, inte enkelverkande normalt öppen eller enkelverkande normalt stängd (sida 499, 512).","message_en":"The body option W exists only double acting, not single acting normally open or single acting normally closed (pages 499, 512).","goto_step":"mhz2-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"K"]},{"in":[{"var":"action"},["D"]]}]},"message_sv":"Kroppsalternativet K finns bara enkelverkande normalt öppen eller enkelverkande normalt stängd, inte dubbelverkande (sida 499, 512).","message_en":"The body option K exists only single acting normally open or single acting normally closed, not double acting (pages 499, 512).","goto_step":"mhz2-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"M"]},{"in":[{"var":"action"},["D"]]}]},"message_sv":"Kroppsalternativet M finns bara enkelverkande normalt öppen eller enkelverkande normalt stängd, inte dubbelverkande (sida 499, 512).","message_en":"The body option M exists only single acting normally open or single acting normally closed, not double acting (pages 499, 512).","goto_step":"mhz2-body"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"in":[{"var":"mto"},["X50"]]}]},"message_sv":"Utan magnet (-X50) kan ingen givare monteras — standardutförandet har inbyggd magnet (sida 496–499).","message_en":"Without the magnet (-X50) no auto switch can be mounted — the standard version has a built-in magnet (pages 496–499).","goto_step":"mhz2-mto"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch"},""]},{"or":[{"!=":[{"var":"lead"},""]},{"!=":[{"var":"count"},""]}]}]},"message_sv":"Kabellängd och antal hör till givaren — välj en givare först.","message_en":"Lead wire length and quantity belong to the auto switch — choose a switch first.","goto_step":"mhz2-switch"},{"severity":"error","if_json":{"and":[{"in":[{"var":"switch"},["F8N","F8P","F8B"]]},{"in":[{"var":"bore"},["10"]]}]},"message_sv":"D-F8N/F8P/F8B passar inte ø10 (sida 497, tabellen).","message_en":"D-F8N/F8P/F8B does not fit ø10 (page 497, table).","goto_step":"mhz2-switch"},{"severity":"error","if_json":{"and":[{"in":[{"var":"count"},["3","4"]]},{"==":[{"var":"bore"},"6"]}]},"message_sv":"ø6 beställs med en (S) eller två givare; antal n finns bara för ø10–40 (sida 496–498).","message_en":"ø6 is ordered with one (S) or two auto switches; the quantity n exists only for ø10–40 (pages 496–498).","goto_step":"mhz2-count"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"lead"},""]},{"in":[{"var":"switch"},["M9NA","M9NAV","M9PA","M9PAV","M9BA","M9BAV"]]}]},"message_sv":"Kabellängd 0,5 m (ingen bokstav) tillverkas på beställning för D-M9NA/M9PA/M9BA (även V-typerna) (sida 496–498, ○).","message_en":"Lead wire length 0.5 m (no letter) is produced upon receipt of order for D-M9NA/M9PA/M9BA (V types too) (pages 496–498, ○).","goto_step":"mhz2-lead"},{"severity":"error","if_json":{"and":[{"==":[{"var":"lead"},"M"]},{"in":[{"var":"switch"},["F8N","F8P","F8B"]]}]},"message_sv":"Kabellängd 1 m (M) finns inte för D-F8N/F